"""
author:wjw
分析:按照高度来找长度最大的区间。
"""

import time
class Solution:
    def largestRectangleArea(self,heights):

        validheights=list(set(heights))
        validheights.sort()
                
        ans=0
        n=len(heights)
        if len(validheights)==1:
            return validheights[0]*n

        for height in validheights:
            maxlength=0
            left=-1
            for i in range(n):
                if heights[i]>=height and left==-1:
                    left=i
                if  heights[i]<height and left!=-1:
                    maxlength=max(i-left,maxlength)
                    left=-1
                if i==n-1 and left!=-1:
                    maxlength=max(i-left+1,maxlength)


            ans=max(ans,height*maxlength)
        return ans


t1=time.time()
heights=[2,4]
heights=[2,1,5,6,2,3]
